import{_ as o,o as t,c as n,a6 as a}from"./chunks/framework.ZMCvXf1_.js";const m=JSON.parse('{"title":"Non-interactive operation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/automation/non-interactive.md","filePath":"guide/automation/non-interactive.md"}'),d={name:"guide/automation/non-interactive.md"};function i(r,e,s,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="non-interactive-operation" tabindex="-1">Non-interactive operation <a class="header-anchor" href="#non-interactive-operation" aria-label="Permalink to “Non-interactive operation”">​</a></h1><p>CI runners, deploy scripts, and AI subagents don&#39;t get to &quot;press Enter&quot;. noorm&#39;s CLI defaults to assuming a human is at the keyboard for a handful of commands; the universal <code>--yes</code> / <code>NOORM_YES</code> opt-in tells those commands to stop asking.</p><p><code>--yes</code> does not mean &quot;do anything regardless.&quot; It means: &quot;use defaults, don&#39;t prompt, fail loudly if a non-interactive path doesn&#39;t exist for this command.&quot;</p><h2 id="the-opt-in" tabindex="-1">The opt-in <a class="header-anchor" href="#the-opt-in" aria-label="Permalink to “The opt-in”">​</a></h2><h3 id="flag-form" tabindex="-1">Flag form <a class="header-anchor" href="#flag-form" aria-label="Permalink to “Flag form”">​</a></h3><p>Every TTY-gated command accepts <code>--yes</code> (alias <code>-y</code>):</p><pre><code>noorm init --yes
</code></pre><h3 id="environment-form" tabindex="-1">Environment form <a class="header-anchor" href="#environment-form" aria-label="Permalink to “Environment form”">​</a></h3><p><code>NOORM_YES</code> is equivalent and applies to every command at once. Useful in CI where you set it once at the top of the pipeline.</p><pre><code>export NOORM_YES=1
noorm init
noorm change ff
noorm db reset
</code></pre><p>Truthy values: <code>1</code>, <code>true</code>, <code>yes</code>, <code>TRUE</code>, any non-empty string. Falsy values: <code>0</code>, <code>false</code>, empty string, unset. The comparison for <code>false</code> is case-insensitive.</p><p>The <code>--yes</code> flag wins over <code>NOORM_YES=0</code>. Use that if you want to override a globally-set falsy default.</p><h2 id="what-yes-does-per-command" tabindex="-1">What <code>--yes</code> does per command <a class="header-anchor" href="#what-yes-does-per-command" aria-label="Permalink to “What --yes does per command”">​</a></h2><p>Some commands have a genuine non-interactive equivalent — for those, <code>--yes</code> succeeds. The rest are interactive by design; for them, <code>--yes</code> errors fast and points at the headless alternative.</p><h3 id="accepts-yes-proceeds" tabindex="-1">Accepts <code>--yes</code> (proceeds) <a class="header-anchor" href="#accepts-yes-proceeds" aria-label="Permalink to “Accepts --yes (proceeds)”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Behavior with <code>--yes</code></th></tr></thead><tbody><tr><td><code>noorm init</code></td><td>Skips all prompts. Requires an existing identity at <code>~/.noorm/identity.{key,pub,json}</code>. Errors with a bootstrap hint if missing.</td></tr></tbody></table><h3 id="refuses-yes-redirect-hint" tabindex="-1">Refuses <code>--yes</code> (redirect hint) <a class="header-anchor" href="#refuses-yes-redirect-hint" aria-label="Permalink to “Refuses --yes (redirect hint)”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Redirect</th></tr></thead><tbody><tr><td><code>noorm sql repl</code></td><td>Use <code>noorm sql query &quot;&lt;SQL&gt;&quot;</code> or <code>noorm sql query --file query.sql</code>.</td></tr><tr><td><code>noorm settings edit</code></td><td>Edit <code>settings.yml</code> directly; run <code>noorm settings build</code> to validate.</td></tr><tr><td><code>noorm settings secret</code></td><td>Edit the <code>secrets:</code> section of <code>settings.yml</code> directly. For values, use <code>noorm secret set &lt;key&gt; &lt;value&gt;</code>.</td></tr></tbody></table><p>These commands exit 2 (bad invocation) with the redirect message on stderr. Same exit code as their TTY refusal, so a pipeline sees one code whichever way it hit the gate.</p><h3 id="already-non-interactive-no-yes-needed" tabindex="-1">Already non-interactive (no <code>--yes</code> needed) <a class="header-anchor" href="#already-non-interactive-no-yes-needed" aria-label="Permalink to “Already non-interactive (no --yes needed)”">​</a></h3><p>These accept explicit flags and don&#39;t gate on a TTY:</p><ul><li><code>noorm identity init --name &quot;...&quot; --email &quot;...&quot;</code> — bootstraps the identity used by <code>noorm init --yes</code>.</li><li><code>noorm config import &lt;path&gt;</code> — wizard-free config setup.</li><li><code>noorm ci init</code> / <code>ci secrets</code> / <code>ci identity new</code> — the dedicated CI bootstrap surface.</li></ul><p>One exception inside that surface: <code>noorm ci identity enroll</code> <strong>does</strong> need <code>--yes</code> (or <code>NOORM_YES=1</code>). It ends in a <code>vault:propagate</code> grant, which the matrix marks <code>confirm</code> for every role that holds it, and sealing the vault key to a public key cannot be undone.</p><h2 id="ci-bootstrap-pipeline" tabindex="-1">CI bootstrap pipeline <a class="header-anchor" href="#ci-bootstrap-pipeline" aria-label="Permalink to “CI bootstrap pipeline”">​</a></h2><p>End-to-end happy path: from a clean machine to a usable noorm project, with no prompts:</p><pre><code>#!/usr/bin/env bash
set -euo pipefail

# 1. Identity (once per machine; exits 1 if one already exists).
noorm identity init \\
  --name &quot;$CI_USER&quot; \\
  --email &quot;$CI_EMAIL&quot;

# 2. Project scaffold (sql/, changes/, settings.yml, state.enc).
cd &quot;$PROJECT_ROOT&quot;
noorm init --yes

# 3. Connection config — env-only, no wizard.
export NOORM_CONNECTION_DIALECT=postgres
export NOORM_CONNECTION_HOST=&quot;$DB_HOST&quot;
export NOORM_CONNECTION_DATABASE=&quot;$DB_NAME&quot;
export NOORM_CONNECTION_USER=&quot;$DB_USER&quot;
export NOORM_CONNECTION_PASSWORD=&quot;$DB_PASSWORD&quot;

# 4. Build schema + apply pending changes.
noorm run build
noorm change ff
</code></pre><p>Step 1 is not idempotent, and under <code>set -e</code> it aborts the script if an identity already exists. Replacing one takes <code>--force --yes</code> together, mints a fresh keypair, and leaves any state encrypted under the old key unreadable. Guard it instead of passing <code>--force</code> blind:</p><pre><code>[ -f ~/.noorm/identity.key ] || noorm identity init \\
  --name &quot;$CI_USER&quot; --email &quot;$CI_EMAIL&quot;
</code></pre><p>The raw <code>--yes</code> flag is required for a replacement; an ambient <code>NOORM_YES</code> deliberately does not satisfy it.</p><p>If you need a stored config (rather than env-only), use <code>noorm config import &lt;path&gt;</code> with a pre-built JSON file. See <a href="./../../headless.html"><code>docs/headless.md</code></a> for the full env-only matrix.</p><h2 id="when-yes-is-not-enough" tabindex="-1">When <code>--yes</code> is NOT enough <a class="header-anchor" href="#when-yes-is-not-enough" aria-label="Permalink to “When --yes is NOT enough”">​</a></h2><p><code>--yes</code> covers prompts. It does NOT relax safety gates that exist for destructive operations:</p><ul><li><code>noorm db drop</code>, <code>noorm db reset</code>, <code>noorm db teardown</code> still require <code>--yes</code> per their own contracts. <code>NOORM_YES=1</code> does count toward those gates.</li><li>Every destructive command is also gated by the config&#39;s access role (<code>viewer</code>/<code>operator</code>/<code>admin</code> — see <a href="./../../headless.html#access-roles">Access Roles</a>). <code>--yes</code>/<code>NOORM_YES=1</code> only satisfies a <code>confirm</code> cell; it cannot open a <code>deny</code> cell. A <code>viewer</code>- or <code>operator</code>-role config still refuses <code>db teardown</code> no matter how many flags you pass.</li><li>Vault and identity operations that need a private key still need the key — either on disk at <code>~/.noorm/identity.key</code> or in <code>$NOORM_IDENTITY_PRIVATE_KEY</code>.</li></ul><p>If a command refuses with a useful error in interactive mode, it refuses with the same error in <code>--yes</code> mode. The flag turns prompts off, not preconditions off.</p>`,34)])])}const u=o(d,[["render",i]]);export{m as __pageData,u as default};
